 913		pos := p.pos
 914		p.expect(token.Return)
 915	
 916		var x Expr
 917		if p.token != token.Semicolon && p.token != token.RBrace {
 918			x = p.parseExpr()
 919		}
 920		p.expectSemi()
 921		return &ReturnStmt{
 922			ReturnPos: pos,
 923			Result:    x,
 924		}
 925	}
