627	func (p *Parser) parseIdent() *Ident {
628		pos := p.pos
629		name := "_"
630	
631		if p.token == token.Ident {
632			name = p.tokenLit
633			p.next()
634		} else {
635			p.expect(token.Ident)
636		}
637		return &Ident{
638			NamePos: pos,
639			Name:    name,
